function save(next){if(storageBlocked)throw Error('存档异常或已在其他页面变化，请先导出当前内容并重新载入，不覆盖现有记录。');try{const current=localStorage.getItem(KEY);if(current!==lastStored){storageBlocked=true;throw Error('另一页面已更新存档，请重新载入后操作。');}const text=JSON.stringify(next);localStorage.setItem(KEY,text);lastStored=text;S=next;storageOK=true;storageWarning='';return true;}catch(e){storageOK=false;throw Error('本机保存失败：此次操作未提交。请导出备份并检查浏览器存储；不要当作已经交接。');}}
function run(type,id,payload={},version,callback){try{const t=task(id);if(['start','submit'].includes(type)&&payload.outcome!=='already_exists'){const why=flowGuard(t);if(why)throw Error(why);}const n=C.applyCommand(S,U.actor,{type,id,version:version??t?.version,payload,requestId:crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random()});save(n);render();if(callback)callback();return true;}catch(e){const err=$('#formError');if(err){err.textContent=e.message;err.classList.add('show');err.scrollIntoView({block:'nearest'});}toast(e.message,true);return false;}}
