function scopedTasks(){return U.scope==='team'?S.tasks:S.tasks.filter(t=>t.owner===U.actor||t.verifier===U.actor&&t.status==='review');}
function summary(p,days=7){const start=C.addDays(S.completeThrough,-days+1);return C.aggregateWindow(S,p.id,C.datesBetween(start,S.completeThrough),'cr').data;}
function allConflicts(){const rows=[];const seen=new Set();for(const t of S.tasks.filter(x=>!C.CLOSED.has(x.status))){for(const c of C.conflicts(S,t)){const key=c.type==='policy'?t.id+'-'+c.id:[t.id,c.id].sort().join('|')+c.type;if(seen.has(key))continue;seen.add(key);rows.push({task:t,...c});}}return rows.sort((a,b)=>(a.level==='hard'?0:1)-(b.level==='hard'?0:1));}
