function timelineHTML(){const start=C.addDays(S.clock,-2),dates=Array.from({length:9},(_,i)=>C.addDays(start,i)),ts=S.tasks.filter(t=>t.productId&&['main_image','ad_budget','video','video_check','purchase','size_info'].includes(t.kind)).slice(0,8);return `<div class="timeline-wrap"><div class="timeline"><div class="timeline-head"><span>动作 / 端口</span>${dates.map(d=>`<span>${d.slice(5)}${d===S.clock?' · 今天':''}</span>`).join('')}</div>${ts.map(t=>{const from=t.effectiveAt?C.shanghaiDay(t.effectiveAt):t.plannedStart,to=t.effectiveAt?C.addDays(from,Math.max(...(t.plan?.milestones||[0]))):t.observationEnd;let x=Math.max(0,C.dayDiff(start,from)),end=Math.min(8,C.dayDiff(start,to));const hidden=x>8||end<0;const tone=C.blocking(S,t)?'red':t.status==='done'?'':t.status==='running'?'blue':'amber';return `<div class="timeline-row"><div class="timeline-label"><button class="plain-link" data-act="open-task" data-id="${t.id}"><b>${esc(t.title)}</b></button><span class="meta">${esc(user(t.owner).dept)} · ${stateNames[t.status]}</span></div>${hidden?'<span class="meta" style="grid-column:2 / 11;padding-left:9px">不在本时间带 · 历史任务仍可查看</span>':`<button class="timeline-bar ${tone}" style="grid-column:${x+2} / ${Math.max(x+3,end+3)};border:0" data-act="open-task" data-id="${t.id}">${t.status==='done'?'已生效 / 观察':'计划与执行'} ${from.slice(5)}</button>`}</div>`;}).join('')}</div></div>`;}
