function trackingView(){const ts=S.tasks.filter(t=>t.plan?.enabled);return head('OUTCOME FOLLOW-UP','执行结束后，继续观察结果','观察计划按动作生效时间计算，不使用新品上架阶段代替；自动化仅在本页面演示。',btn('生成评估快照','evaluate','','primary','chart'))+
 notice('3 / 7日等窗口是可修改的演示配置，不是已批准的业务阈值。生效当天不进入前后完整日窗口；缺日不补零，前后变化不证明因果。')+
 `<div class="grid3">${ts.map(t=>{const m=t.plan.milestones.at(-1),r=C.evaluate(S,t,m);return `<article class="report-card"><div class="mini-header">${reportStatus(r)}<span class="meta">计划 v${t.plan.version} · ${m}日节点</span></div><h3>${esc(t.title)}</h3><div class="meta">${esc(product(t.productId)?.name)}<br>生效：${t.effectiveAt?C.shanghaiDay(t.effectiveAt):'尚未核验'} · 指标：${t.plan.metric==='cr'?'商品日加权UVCR':'日均支付金额'}</div>${r.status==='ready'?`<div class="effect-number">${r.delta>=0?'+':''}${t.plan.metric==='cr'?(r.delta*100).toFixed(2):r.delta.toFixed(0)}<span>${t.plan.metric==='cr'?'个百分点':'元/日'}</span></div><div class="meta">${t.plan.metric==='cr'?pct(r.before.value):num(r.before.value)} → ${t.plan.metric==='cr'?pct(r.after.value):num(r.after.value)}</div>`:`<div class="mutedbox meta">${esc(r.message)}</div>`}<div class="bottom">${btn('查看跟踪','open-task',`data-id="${t.id}" data-tab="track"`,'text')}${status(t)}</div></article>`;}).join('')}</div>`+
 panel('已经生成的评估快照','不同计划版本和数据结果分别保留；同样的数据不重复生成通知。',`<div class="table-wrap"><table><thead><tr><th>报告</th><th>任务</th><th>观察节点</th><th>结果</th><th>数据 / 计划版本</th><th>查看</th></tr></thead><tbody>${S.reports.slice(0,20).map(r=>`<tr><td class="mono">${r.id}</td><td>${esc(task(r.taskId)?.title)}</td><td>生效后 ${r.milestone} 个完整日</td><td>${reportStatus(r)}</td><td>数据 v${r.dataVersion} / 计划 v${r.planVersion}</td><td>${btn('报告','report',`data-id="${r.id}"`,'text')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">尚无评估快照。</td></tr>'}</tbody></table></div>`);}
function runState(){return `<div class="stats">${stat('本机存档',storageOK?'可用':'受限','只在此浏览器，不是共享存储','','file')}${stat('真实外部连接','未接入','飞书 / CLI / LLM / 璇玑均未连接','','link')}${stat('Mac执行端模拟',S.flags.macOnline?'在线':'离线','仅交互开关，不检测真实Mac状态',S.flags.macOnline?'teal':'red','activity')}${stat('待模拟通知',S.notifications.filter(n=>n.status==='pending').length,'保存任务在前，通知在后','','bell')}</div>`+
 `<div class="grid2">${panel('演示控制台','可用于比赛演示异常分支；不启动后台任务。',`<div class="panel-body"><div class="actions" style="margin-bottom:12px">${btn(S.flags.macOnline?'模拟Mac离线':'模拟Mac恢复','mac-toggle','','small')}${btn(S.flags.syncFail?'关闭模拟回写失败':'模拟回写失败','sync-toggle','','small')}${btn('模拟回写与通知','sync','','small')}</div><div class="actions">${btn('模拟后续7天数据到齐','advance','','small')}${btn('重读相同来源','refresh','','small')}${btn('生成效果快照','evaluate','','small')}</div><div class="notice compact blue" style="margin-top:16px">Mac离线的模拟不影响本机反馈；真实多人共享保存必须在第二步接入并验收。关闭此HTML后没有定时计算。</div></div>`)}${panel('同一次工作，状态分开记录','不把“已点击”当作“已经交接”。',`<div class="panel-body">${[['1','任务与回执','本地事务先保存','本机演示'],['2','回写飞书摘要','写任务ID、有效状态、版本','未接入'],['3','消息触达','发送后保存回执；失败可重试','未接入'],['4','经营效果','数据到齐后按计划计算','本地计算']].map(([n,a,b,c])=>`<div class="run-step"><span class="n">${n}</span><div><b>${a}</b><p>${b}</p></div>${B(c)}</div>`).join('')}</div>`)}</div>`+
 panel('通知队列（仅演示）','点击入口可直达同一任务；演示发送不代表任何人真正收到飞书消息。',`<div class="table-wrap"><table><thead><tr><th>任务</th><th>通知类型</th><th>接收角色</th><th>状态</th><th>入口</th></tr></thead><tbody>${S.notifications.slice(0,18).map(n=>`<tr><td class="mono">${n.taskId}</td><td>${esc(n.type)}</td><td>${esc(user(n.recipient).name)}</td><td>${B(n.status==='simulated'?'已演示发送':n.status==='failed'?'模拟发送失败':'待模拟发送',n.status==='simulated'?'green':n.status==='failed'?'red':'gray')}</td><td>${btn('打开任务','open-task',`data-id="${n.taskId}"`,'text')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无通知；任务保存后才入队。</td></tr>'}</tbody></table></div>`);}
function runSource(){return notice('以下名称与约束来自已上传SOP；表内状态与日期为演示，不代表本轮访问成功。')+panel('来源索引的只读引用','不在Demo中复制一份可编辑的来源配置，不直接执行本地共享盘路径。',`<div class="table-wrap"><table><thead><tr><th>来源模块</th><th>引用</th><th>示例日期</th><th>示例状态</th><th>边界</th></tr></thead><tbody>${S.sources.map(s=>`<tr><td>${esc(s.name)}</td><td class="meta">${esc(s.ref)}</td><td class="nowrap">${s.dataDate}</td><td>${B(s.status==='success'?'演示已到数':'演示读取失败',s.status==='success'?'green':'red')}</td><td class="text-break" style="min-width:240px">${esc(s.note)}</td></tr>`).join('')}</tbody></table></div>`)+`<h2 class="section-title">必须保持的原规则</h2><div class="grid3">${[['新品与阶段','T−29至T；文本ID；归档和LIST分开。T+3/T+7/T+14具体动作继续依赖原细则，不在本Demo推导。'],['经营数据','完整销售日D；近30天销售、Concept×二级类目近7完整日基准。缺失不补0，不直接平均每日CR。'],['来源和安全','seasonal不回退season2；库存先按ID核验。来源记录不等于完成；不运行automation-3、不发送外部消息。']].map(([a,b])=>`<div class="policy-card"><h3>${a}</h3><p>${b}</p></div>`).join('')}</div>`;}
