function runConnectV8(){return notice('第二步才接真实任务和共享保存。本页列的是适配建议，不宣称已有接口、账号或服务。')+`<div class="integration-grid"><div class="integration-box"><h3>① 继续使用Mac上游</h3><p>核验后的LIST、阶段清单和质量状态。只传允许的摘要，不重新实现T+规则，不复制共享原始明细。</p></div><div class="integration-box"><h3>② 共享任务与反馈</h3><p>登录、任务ID、版本检查、附件引用、回执、核验和审计。优先复用璇玑已有能力，再选存储。</p></div><div class="integration-box"><h3>③ 同步与跟踪</h3><p>CLI消息链接直达任务；任务多维表回写摘要，新品保持普通Sheets。跟踪服务检查数据完整性，通知失败可补发。</p></div></div><h2 class="section-title">最小适配契约 · 建议字段，不是现有表头</h2><div class="code">upstream snapshot  → snapshot_id / business_date_T / complete_sales_day_D\n                    products[] / existing_stage_actions[] / source_statuses[]\n\nwork item          → task_id / requirement_id / product_id / owner_id\n                    input_version / output_version / record_version\n\nexecution receipt  → task_id / submitted_by / actual_effective_at\n                    artifact_version / evidence_ref / review_result\n\ntracking result    → action_id / plan_version / observation_window\n                    data_snapshot_id / completeness / report_version\n\n规则：任务先保存，再通知；任务与反馈只有一个有效写入来源。</div><div class="actions" style="margin-top:17px">${btn('导出演示备份 JSON','backup','','','download')}${btn('导入V9演示备份','import-backup')}${btn('重置本机演示','reset','','danger')}</div><p class="source-ref">备份只供本原型恢复，不是现有飞书字段映射格式；不支持直接上传真实经营原始明细。</p>`;}
async function leaveDrawer(){const dirty=$('#taskForm')?.dataset.dirty==='yes';if(dirty&&!await window.__hmConfirm('当前有尚未提交的回执。关闭会丢弃本次未暂存修改，是否继续？'))return false;closeDrawer();return true;}
function closeDrawer(){U.drawer=null;$('#drawerback').classList.remove('open');$('#drawer').innerHTML='';document.body.style.overflow='';attachments=[];if(location.hash.startsWith('#task='))history.replaceState(null,'',location.pathname+location.search);if(lastFocus&&lastFocus.isConnected)lastFocus.focus();}
