 $('#sidebar').innerHTML=`<div class="brand"><div class="brandmark">HM</div><div class="brand-copy"><strong>运营工作台</strong><small>OPERATIONS · V9</small></div></div><div class="nav-caption">从经营差异到可靠交付</div>${[['core','chart','核心数据','01'],['diagnostic','search','店铺诊断','02'],['tasks','task','待办事项','03']].map(([k,ic,n,no])=>`<button class="navbtn ${area===k?'active':''}" data-act="nav" data-view="${k}" title="${n}">${ico(ic)}<b>${n}</b>${k==='tasks'?`<span class="count">${open}</span>`:`<small>${no}</small>`}</button>`).join('')}<div class="sidebar-context"><span class="dot"></span> 经营按完整日更新<br><small>任务反馈独立于经营刷新</small></div><div class="sidebar-bottom"><button data-act="nav" data-view="runs" title="数据与规则">${ico('settings')}<span>数据与规则</span></button><button data-act="themes" title="主题配色">${ico('bulb')}<span>主题 · ${THEMES.find(x=>x[0]===U.theme)?.[1]}</span></button><button data-act="guide" title="演示说明">${ico('book')}<span>演示与交接说明</span></button><div class="brand-chip">V9 DISCUSSION DEMO</div></div>`;
